//Hija de Dispositivo.Implementa Medible y Alertable
public class SensorHumo extends Dispositivo implements Medible, Alertable {

    // Atributos
    private double concentracion;


    // Constructor vacio
    public SensorHumo() {
        super();
        encendido = true;
        concentracion = 0;
    }


    // Constructor completo
    public SensorHumo(String codigo, Oficina oficina, double potenciaNominal) {
        super(codigo, oficina, potenciaNominal);
        encendido = true;
        concentracion = 0;
    }


    // Getter del nuevo atributo
    public double getConcentracion() {
        return concentracion;
    }


    // Registrar lectura (Medible). Recibe en ppm, verifica que sea entre 0 y 1000, y devuelve mi codigo de valores para ver si se genera o no una alerta
    @Override
    public int registrarLectura(double valor) {
        if (!encendido) {
			//No válido, -1
            return -1;
        }
        if (valor < 0 || valor > 1000 || Double.isNaN(valor) || Double.isInfinite(valor)) {
            return -1;
        }
        // Guarda la lectura solamente si es valida
        concentracion = valor;

        // Critica
        if (valor >= 300) {
            return 3;
        }

        // Alta
        else if (valor >= 150) {
            return 2;
        }

        // Normal
        return 0;
    }


    // Genera Alerta, dados el codigo, Severidad y hora

    @Override
    public Alerta generarAlerta(int codigo, Severidad severidad, int horaSimulacion) {

        if (severidad == null || codigo <= 0 || horaSimulacion < 0) {
            return null;
        }

        String mensaje = "Concentracion de humo de " + concentracion + " ppm registrada por el sensor " + this.codigo;

        return new Alerta(codigo, this, horaSimulacion, severidad, mensaje);
    }


    // Calcular consumo por hora. Solo es la potencia /1000 para tenerla en kW

    @Override
    public double calcularConsumoHora() {
        return potenciaNominal / 1000.0;
    }


    // toString
    @Override
    public String toString() {
        return super.toString() + "\nUltima concentracion: " + concentracion + " ppm";
    }
}
